qrList.message:
/if left="{{lastCharMessage}}" right="[D20_REQUEST]" rule=in
else={
    /pass ""
}
{
    /if left="{{getvar::d20_tiandao}}" right="" rule=eq
    else={
        /pass ""
    }
    {
        /setvar key=d20_tiandao 0
        ||
    }

    /if left="{{getvar::d20_pending}}" right="1" rule=eq
    else={
        /pass "{{lastCharMessage}}" |
        /regex name="D20_提取ACTION" |
        /setvar key=d20_action |

        /pass "{{lastCharMessage}}" |
        /regex name="D20_提取DC" |
        /setvar key=d20_dc |

        /pass "{{lastCharMessage}}" |
        /regex name="D20_提取MOD" |
        /setvar key=d20_mod |

        /pass "{{lastCharMessage}}" |
        /regex name="D20_提取DETAIL" |
        /setvar key=d20_detail |

        /setvar key=d20_rerolled 0
        ||

        /pass {{roll::1d20}} |
        /setvar key=d20_lastroll |

        /add {{getvar::d20_lastroll}} {{getvar::d20_mod}} |
        /setvar key=d20_final |

        /sub {{getvar::d20_final}} {{getvar::d20_dc}} |
        /setvar key=d20_diff

        ||

        /setvar key=d20_result "未判定"

        ||

        /if left="{{getvar::d20_lastroll}}" right="20" rule=eq
        else={
            /if left="{{getvar::d20_lastroll}}" right="1" rule=eq
            else={
                /if left="{{getvar::d20_diff}}" right="5" rule=gte
                else={
                    /if left="{{getvar::d20_diff}}" right="0" rule=gte
                    else={
                        /if left="{{getvar::d20_diff}}" right="-2" rule=gte
                        else={
                            /if left="{{getvar::d20_diff}}" right="-5" rule=gte
                            else={
                                /if left="{{getvar::d20_diff}}" right="-9" rule=gte
                                else={
                                    /setvar key=d20_result "惨重失败"
                                }
                                {
                                    /setvar key=d20_result "严重失败"
                                }
                            }
                            {
                                /setvar key=d20_result "普通失败"
                            }
                        }
                        {
                            /setvar key=d20_result "接近失败"
                        }
                    }
                    {
                        /setvar key=d20_result "成功"
                    }
                }
                {
                    /setvar key=d20_result "优秀成功"
                }
            }
            {
                /setvar key=d20_result "大失败"
            }
        }
        {
            /setvar key=d20_result "大成功"
        }

        ||

        /setvar key=d20_pending 1

        ||

        /inject id="xiuxian_d20_result" position=chat depth=0 role=system "[D20_ENGINE_RESULT]
ACTION={{getvar::d20_action}}
DC={{getvar::d20_dc}}
MOD={{getvar::d20_mod}}
DETAIL={{getvar::d20_detail}}
RAW={{getvar::d20_lastroll}}
FINAL={{getvar::d20_final}}
DIFF={{getvar::d20_diff}}
RESULT={{getvar::d20_result}}
[/D20_ENGINE_RESULT]

[D20_SETTLEMENT_PENDING]
当前结果仅为待结算候选结果，尚未收到[D20_ACCEPT]。禁止把本次ACTION的结果写入正式世界状态；USER只能接受当前结果或进行天道重Roll。"

        ||

        /echo "【D20判定】

修正因素：
{{getvar::d20_detail}}

综合修正：{{getvar::d20_mod}}

判定结果：{{getvar::d20_result}}

请选择【✅接受结果】或【☯天道重Roll】。"
    }
    {
        /echo "⚠️ 当前已有D20判定等待处理。"
    }
}

/echo "【D20系统状态】
天道点：{{getvar::d20_tiandao}}/5
待结算：{{getvar::d20_pending}}
是否重Roll：{{getvar::d20_rerolled}}
最近D20：{{getvar::d20_lastroll}}
ACTION：{{getvar::d20_action}}
DC：{{getvar::d20_dc}}
MOD：{{getvar::d20_mod}}
DETAIL：{{getvar::d20_detail}}
最终值：{{getvar::d20_final}}
差值：{{getvar::d20_diff}}
结果等级：{{getvar::d20_result}}"

/if left="{{getvar::d20_pending}}" right="1" rule=eq
else={
    /echo "⚠️ 当前没有处于待结算状态的D20判定，无法重Roll。"
}
{
    /if left="{{getvar::d20_tiandao}}" right="0" rule=gt
    else={
        /echo "⚠️ 天道点不足，无法重Roll。当前：{{getvar::d20_tiandao}}/5"
    }
    {
        /decvar d20_tiandao
        ||
        /setvar key=d20_rerolled 1
        ||
        /pass {{roll::1d20}} |
        /setvar key=d20_lastroll |
        /add {{getvar::d20_lastroll}} {{getvar::d20_mod}} |
        /setvar key=d20_final |
        /sub {{getvar::d20_final}} {{getvar::d20_dc}} |
        /setvar key=d20_diff
        ||
        /setvar key=d20_result "未判定"
        ||
        /if left="{{getvar::d20_lastroll}}" right="20" rule=eq
        else={
            /if left="{{getvar::d20_lastroll}}" right="1" rule=eq
            else={
                /if left="{{getvar::d20_diff}}" right="5" rule=gte
                else={
                    /if left="{{getvar::d20_diff}}" right="0" rule=gte
                    else={
                        /if left="{{getvar::d20_diff}}" right="-2" rule=gte
                        else={
                            /if left="{{getvar::d20_diff}}" right="-5" rule=gte
                            else={
                                /if left="{{getvar::d20_diff}}" right="-9" rule=gte
                                else={: /setvar key=d20_result "惨重失败" :}
                                {: /setvar key=d20_result "严重失败" :}
                            }
                            {: /setvar key=d20_result "普通失败" :}
                        }
                        {: /setvar key=d20_result "接近失败" :}
                    }
                    {: /setvar key=d20_result "成功" :}
                }
                {: /setvar key=d20_result "优秀成功" :}
            }
            {: /setvar key=d20_result "大失败" :}
        }
        {: /setvar key=d20_result "大成功" :}
        ||
        /setvar key=d20_pending 1
        ||
        /inject id="xiuxian_d20_result" position=chat depth=0 role=system "[D20_REROLL_RESULT]
ACTION={{getvar::d20_action}}
DC={{getvar::d20_dc}}
MOD={{getvar::d20_mod}}
DETAIL={{getvar::d20_detail}}
RAW={{getvar::d20_lastroll}}
FINAL={{getvar::d20_final}}
DIFF={{getvar::d20_diff}}
RESULT={{getvar::d20_result}}
[/D20_REROLL_RESULT]

[D20_SETTLEMENT_PENDING]
本次重Roll结果已经永久替代旧骰点。当前结果仍仅为待结算候选结果，尚未收到[D20_ACCEPT]。禁止把本次ACTION的结果写入正式世界状态。"
        ||
        /echo "☯ 天道重Roll完成
ACTION={{getvar::d20_action}}
DC={{getvar::d20_dc}}
MOD={{getvar::d20_mod}}
DETAIL={{getvar::d20_detail}}
新RAW={{getvar::d20_lastroll}}
最终值={{getvar::d20_final}}
差值={{getvar::d20_diff}}
结果等级={{getvar::d20_result}}
PENDING={{getvar::d20_pending}}
剩余天道点={{getvar::d20_tiandao}}/5
旧骰点已经永久作废，本次新骰点必须替代旧结果。"
    }
}

/if left=d20_tiandao right=5 rule=lt
else={
    /echo "天道点已经达到上限：5/5"
}
{
    /incvar d20_tiandao |
    /echo "获得1点天道点。当前：{{getvar::d20_tiandao}}/5"
}
